def colorTheArray(n: int, queries: List[List[int]]) -> List[int]:
    nums = [0] * n
    answer = []
    count = 0

    for index, color in queries:
        # Before changing, remove contributions from neighbors
        if index > 0 and nums[index] != 0:
            if nums[index] == nums[index - 1]:
                count -= 1
        if index < n - 1 and nums[index] != 0:
            if nums[index] == nums[index + 1]:
                count -= 1

        # Apply the new color
        nums[index] = color

        # After changing, add contributions from neighbors
        if index > 0 and nums[index - 1] == color:
            count += 1
        if index < n - 1 and nums[index + 1] == color:
            count += 1

        answer.append(count)

    return answer
