def numberOfSubstrings(s: str) -> int:
    n = len(s)
    prefix_zero = [0] * (n + 1)
    for i in range(n):
        prefix_zero[i + 1] = prefix_zero[i] + (1 if s[i] == '0' else 0)

    count = 0

    def is_valid(i, j):
        z = prefix_zero[j + 1] - prefix_zero[i]
        L = j - i + 1
        return L >= z + z * z

    for j in range(n):
        lo, hi = 0, j
        ans_i = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if is_valid(mid, j):
                ans_i = mid
                hi = mid - 1
            else:
                lo = mid + 1

        if ans_i != -1:
            count += j - ans_i + 1

    return count
