from typing import List

def maximumPrimeDifference(nums: List[int]) -> int:
    # 條件列舉：
    # 1. 回傳最大距離（indices 之間的差異）
    # 2. 兩個 prime numbers 的 indices 可以相同（距離為 0）
    # 3. nums.length >= 1, nums[i] in [1, 100]
    # 4. 至少有一個 prime number
    # 5. 最大距離 = 最後一個 prime 的 index - 第一個 prime 的 index

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    first_prime_idx = -1
    last_prime_idx = -1

    for i, num in enumerate(nums):
        if is_prime(num):
            if first_prime_idx == -1:
                first_prime_idx = i
            last_prime_idx = i

    return last_prime_idx - first_prime_idx
