def minimumString(a: str, b: str, c: str):
    def overlap(x, y):
        # Find max overlap where suffix of x == prefix of y
        max_ov = 0
        for i in range(min(len(x), len(y)), 0, -1):
            if x[-i:] == y[:i]:
                max_ov = i
                break
        return max_ov

    def combine(x, y):
        ov = overlap(x, y)
        return x + y[ov:]

    # Try all permutations of (a, b, c)
    from itertools import permutations
    results = set()
    for perm in permutations([a, b, c]):
        s1 = combine(perm[0], perm[1])
        s2 = combine(s1, perm[2])
        results.add(s2)
    return min(results)
